{
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixpkgs-unstable";
    home-manager = {
      url = "github:nix-community/home-manager";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    nix-darwin = {
      url = "github:LnL7/nix-darwin";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    sops-nix = {
      url = "github:Mic92/sops-nix";
      inputs.nixpkgs.follows = "nixpkgs";
    };
    walker.url = "github:abenz1267/walker";
    nixgl.url = "github:guibou/nixGL";
    # Follow our nixpkgs: nixGL pins its own, whose mesa (25.0) predates
    # Panther Lake / Xe3 and deadlocked Hyprland on shiori at startup.
    nixgl.inputs.nixpkgs.follows = "nixpkgs";
    explore-mcp.url = "github:sauyon/explore-mcp";
    explore-mcp.inputs.nixpkgs.follows = "nixpkgs";
    # drovr — CLI for single-writer/compressed-handoff agent phases; ships the
    # `drovr` binary plus drovr:* Claude skills under share/drovr/.
    drovr.url = "git+https://forge.ko.ag/drovr/drovr.git";
    drovr.inputs.nixpkgs.follows = "nixpkgs";
    # Terminal diff viewer for agent changesets; ships a `hunk-review` Claude
    # skill under `${hunk}/skills/`.
    hunk.url = "github:modem-dev/hunk";
    # Matt Pocock's agent skills. Not a flake — a plain tree of SKILL.md
    # bundles under skills/<category>/<name>/, consumed by path below.
    mattpocock-skills.url = "github:mattpocock/skills";
    mattpocock-skills.flake = false;
    # Seamless OIDC SSH gate (gate binary + nixos/darwin modules).
    # forge.ko.ag is the canonical remote (anon-readable over the CF tunnel);
    # codeberg is a stale mirror. Pin here so the lock tracks forge, not codeberg.
    ssh-oidc.url = "git+https://forge.ko.ag/sauyon/ssh-oidc";
    # Private companion to this repo: the git identity, internal endpoints,
    # the new-tab links and the per-host posture home.nix hands the Claude
    # auto-mode classifier. Not a flake -- a plain tree of nix values, like
    # mattpocock-skills above. It is private because a public repo is the
    # wrong place to MAINTAIN values that are of no use to anyone else;
    # credentials are a different problem and stay in secrets.yaml under KMS.
    # Needed at eval time, so a host must be able to read it: locally that is
    # git-credential-fj (home.nix), in CI a netrc line from FORGE_TOKEN.
    dotfiles-private.url = "git+https://forge.ko.ag/sauyon/dotfiles-private.git";
    dotfiles-private.flake = false;
    # Zen browser. Not in nixpkgs (checked against this lock), so it comes from
    # the community flake, which ships the `zen-beta` package plus a
    # home-manager module built on home-manager's own mkFirefoxModule — so
    # `programs.zen-browser` takes the same policies/profiles/extensions/
    # nativeMessagingHosts options `programs.firefox` did. home-manager follows
    # ours so that module generator is the one our lock pins, not a second copy.
    zen-browser.url = "github:0xc000022070/zen-browser-flake";
    zen-browser.inputs.nixpkgs.follows = "nixpkgs";
    zen-browser.inputs.home-manager.follows = "home-manager";
  };

  outputs = { nixpkgs, home-manager, nix-darwin, sops-nix, walker, nixgl, explore-mcp, drovr, hunk, mattpocock-skills, zen-browser, ssh-oidc, dotfiles-private, ... }:
  let
    mkHome = system: machine: home-manager.lib.homeManagerConfiguration {
      pkgs = nixpkgs.legacyPackages.${system};
      extraSpecialArgs = {
        inherit sops-nix walker nixgl explore-mcp drovr hunk mattpocock-skills zen-browser machine;
        inherit dotfiles-private;
        inherit system;
      };
      modules = [ ./home.nix ];
    };
    linuxHome = mkHome "x86_64-linux";
  in {
    homeConfigurations.utsuho = linuxHome {
      hostname = "utsuho";
      gui = true;
      gpu = "amd";
    };
    homeConfigurations.kyuusaku = linuxHome {
      hostname = "kyuusaku";
      gui = false;
      homeDir = "/local/mnt/workspace/kyuusaku";
    };
    homeConfigurations.setsuna = linuxHome {
      hostname = "setsuna";
      gui = true;
    };
    homeConfigurations.shiori = linuxHome {
      hostname = "shiori";
      gui = true;
    };
    homeConfigurations.fujiwara = linuxHome {
      hostname = "fujiwara";
      # Headless: the box has an HDMI display wired up, but no graphical session
      # has run on it since Jun 2025. Dropping the desktop stack (hyprland,
      # waybar, walker, kanshi, portals) rather than leaving units to fail at
      # every activation. Flip back to true if it becomes a workstation again.
      gui = false;
      gpu = "amd";
    };
    homeConfigurations.mari = mkHome "aarch64-darwin" {
      hostname = "mari";
      gui = true;
    };

    darwinConfigurations.mari = nix-darwin.lib.darwinSystem {
      system = "aarch64-darwin";
      modules = [
        sops-nix.darwinModules.sops
        ssh-oidc.darwinModules.default
        ({ config, ... }: {
          programs.zsh.enable = true;
          nix.enable = true;
          nix.settings.experimental-features = [ "nix-command" "flakes" ];

          # Self-hosted attic binary cache (kube cluster); signing key is public.
          # Assumes nix-darwin manages nix (nix.enable = true). If mari moves to
          # Determinate Nix, relocate this to /etc/determinate like the Linux boxes.
          nix.settings.extra-substituters = [ "https://attic.ko.ag/kube" ];
          nix.settings.extra-trusted-public-keys = [ "kube:REDACTED" ];
          # Private cache → read token via netrc, rendered as root by sops-nix.
          sops.secrets.atticPullToken = { };

      "rust"
      "kubectl"
    ];
  };

  sessionVariables = {
    XDG_CONFIG_HOME = "$HOME/.config";
    XDG_DATA_HOME = "$HOME/.local/share";
    XDG_RUNTIME_DIR = "/run/user/$(id -u)";
    _ZO_DOCTOR = "0";

    # Reap detached mosh sessions after a week of client silence.
    #
    # mosh-server has no reconnect timeout by default, so a client that never
    # comes back (closed laptop, dead network) leaves the server — and every
    # process under its pty — alive forever. Nothing downstream breaks the
    # cycle: the shell sees a live parent and a valid tty, so it never gets a
    # HUP, and the TUI under it blocks on a pty nobody will ever write to.
    # Measured 2026-08-28: 16 such servers holding 38 processes and 1.66 GB,
    # aged 21-72 days, every one at zero syscalls.
    #
    # It has to reach .zshenv, not just .zshrc: mosh starts the server via
    # `ssh host mosh-server new`, and sshd runs that as a non-interactive
    # `$SHELL -c`, which reads .zshenv and never .zshrc. This block qualifies —
    # HM emits it into .zshenv under `if [[ ! -o login ]]`, and that is exactly
    # the shell sshd gives us.
    MOSH_SERVER_NETWORK_TMOUT = 7 * 24 * 60 * 60;
  };

  shellAliases = {
    ls = "${pkgs.coreutils}/bin/ls -q --color=auto";
    grep = "${pkgs.gnugrep}/bin/grep --color=auto";
    diff = "${pkgs.diffutils}/bin/diff --color=auto -utr";

    ll = "ls -alhF";
    la = "ls -A";
    l = "ls -FB";

    kc = "kubeconfig";

    # rsync is better.
    rcp = "${pkgs.rsync}/bin/rsync -rgoP";

=== envExtra head
      src = pkgs.zsh-powerlevel10k;
      file = "share/zsh-powerlevel10k/powerlevel10k.zsh-theme";
    }
  ];

  envExtra = ''
    # brew
    if [[ -f /home/linuxbrew/.linuxbrew/bin/brew ]]; then
      eval "$(/home/linuxbrew/.linuxbrew/bin/brew shellenv)"
    elif [[ -f /opt/homebrew/bin/brew ]]; then
      eval "$(/opt/homebrew/bin/brew shellenv)"
    fi

    if command -v mise >/dev/null 2>&1; then
      eval "$(mise activate zsh)"
    fi

    # pnpm
    export PNPM_HOME="/home/sauyon/.local/share/pnpm"
    case ":$PATH:" in
      *":$PNPM_HOME:"*) ;;
      *) export PATH="$PNPM_HOME:$PATH" ;;
    esac
  '';

  initContent = ''
    # ── Utils ──────────────────────────────────────────────────────────────
    if [ -z $_SAUYON_UTILS_RUN ]; then
    _SAUYON_UTILS_RUN=true

    include() { [[ -f "$@" ]] && source "$@" }
